enum class SeqNumState : uint8_t {
	Expected,
	Gap,
	PossDupOld,
	InvalidOld
};

[[nodiscard]] inline static SeqNumState classifySeqNum(int64_t msgSeqNum,
												int64_t expectedSeqNum,
												bool possDup) noexcept {
	if (msgSeqNum == expectedSeqNum) { return SeqNumState::Expected; }
	if (msgSeqNum > expectedSeqNum) {  return SeqNumState::Gap; }
	return possDup ? SeqNumState::PossDupOld : SeqNumState::InvalidOld;
}

